<?php
declare(strict_types=1);
namespace App\Controllers; use App\Core\Request;use App\Core\View;use App\Core\Response;use App\Core\Session;use App\Middleware\PermissionMiddleware;use App\Repositories\UserRepository;
final class UserController {public function index(Request $r):void{PermissionMiddleware::require('users.view');$repo=new UserRepository();$data=$repo->all((string)$r->query('q',''),max(1,(int)$r->query('page',1)),10,auth_user());$roles=$repo->roles(auth_user());View::render('users/index',compact('data','roles'));}public function store(Request $r):void{PermissionMiddleware::require('users.create');verify_csrf();$repo=new UserRepository();$this->assertAssignable($repo,(int)$r->input('role_id'));$id=$repo->create($r->all());$repo->setRole($id,(int)$r->input('role_id'));Session::flash('success','User created.');Response::redirect('/users');}public function update(Request $r,string $id):void{PermissionMiddleware::require('users.edit');verify_csrf();$repo=new UserRepository();$target=$repo->findWithRole((int)$id);if(!$target||(($target['role_name']??'')==='Super Admin'&&(auth_user()['role_name']??'')!=='Super Admin'))throw new \RuntimeException('You cannot modify a Super Admin.');$this->assertAssignable($repo,(int)$r->input('role_id'));$repo->update((int)$id,$r->all());$repo->setRole((int)$id,(int)$r->input('role_id'));Session::flash('success','User updated.');Response::redirect('/users');}private function assertAssignable(UserRepository $repo,int $roleId):void{$role=$repo->roleNameById($roleId);if(!$role)throw new \RuntimeException('Invalid role.');if($role==='Super Admin'&&(auth_user()['role_name']??'')!=='Super Admin')throw new \RuntimeException('Only Super Admin can assign Super Admin.');}}
